{"implementation": "def solve(case):
    """Grammar-guided node reduction for the registered miniature parse-tree task."""

    def fail(message):
        raise ValueError(message)

    if not isinstance(case, dict):
        fail("case must be an object")

    payload = case.get("payload", case)
    if not isinstance(payload, dict):
        fail("payload must be an object")

    if "nodes" not in payload or "required_symbols" not in payload:
        fail("payload is missing required fields")

    nodes = payload["nodes"]
    required_symbols_raw = payload["required_symbols"]
    if not isinstance(nodes, list) or not nodes:
        fail("nodes must be a non-empty list")
    if not isinstance(required_symbols_raw, list):
        fail("required_symbols must be a list")

    required_symbols = []
    seen_required = set()
    for symbol in required_symbols_raw:
        if not isinstance(symbol, str):
            fail("required symbol must be a string")
        if symbol not in seen_required:
            seen_required.add(symbol)
            required_symbols.append(symbol)
    required_set = set(required_symbols)

    required_node_fields = {"id", "parent", "symbol", "depth", "removable", "utility"}
    by_id = {}
    source_index = {}
    normalized_nodes = []

    for index, node in enumerate(nodes):
        if not isinstance(node, dict):
            fail("node must be an object")
        missing = required_node_fields.difference(node)
        if missing:
            fail("node is missing required fields")

        node_id = node["id"]
        parent = node["parent"]
        symbol = node["symbol"]
        depth = node["depth"]
        removable = node["removable"]
        utility = node["utility"]

        if not isinstance(node_id, str) or node_id == "":
            fail("node id must be a non-empty string")
        if node_id in by_id:
            fail("node ids must be unique")
        if parent is not None and not isinstance(parent, str):
            fail("parent must be null or a string")
        if not isinstance(symbol, str):
            fail("symbol must be a string")
        if not isinstance(depth, int) or isinstance(depth, bool) or depth < 0:
            fail("depth must be a non-negative integer")
        if not isinstance(removable, bool):
            fail("removable must be a boolean")
        if not isinstance(utility, (int, float)) or isinstance(utility, bool):
            fail("utility must be numeric")

        normalized = {
            "id": node_id,
            "parent": parent,
            "symbol": symbol,
            "depth": depth,
            "removable": removable,
            "utility": float(utility),
            "source_index": index,
        }
        by_id[node_id] = normalized
        source_index[node_id] = index
        normalized_nodes.append(normalized)

    roots = [node for node in normalized_nodes if node["parent"] is None]
    if len(roots) != 1:
        fail("tree must contain exactly one root")
    root_id = roots[0]["id"]
    if roots[0]["depth"] != 0:
        fail("root depth must be zero")
    if roots[0]["removable"]:
        fail("root must not be removable")

    children = {node["id"]: [] for node in normalized_nodes}
    for node in normalized_nodes:
        parent = node["parent"]
        if parent is None:
            continue
        if parent not in by_id:
            fail("parent id must refer to an existing node")
        if node["depth"] != by_id[parent]["depth"] + 1:
            fail("child depth must be parent depth plus one")
        children[parent].append(node["id"])

    visiting = set()
    visited = set()

    def visit(node_id):
        if node_id in visiting:
            fail("tree must be acyclic")
        if node_id in visited:
            return
        visiting.add(node_id)
        for child_id in sorted(children[node_id]):
            visit(child_id)
        visiting.remove(node_id)
        visited.add(node_id)

    visit(root_id)
    if len(visited) != len(normalized_nodes):
        fail("all nodes must be reachable from the root")

    initial_symbol_counts = {}
    for node in normalized_nodes:
        initial_symbol_counts[node["symbol"]] = initial_symbol_counts.get(node["symbol"], 0) + 1
    for symbol in required_symbols:
        if initial_symbol_counts.get(symbol, 0) <= 0:
            fail("required symbols must be represented")

    retained = set(by_id)
    retained_symbol_counts = dict(initial_symbol_counts)
    removal_order = []
    decisions = []

    candidate_nodes = sorted(normalized_nodes, key=lambda node: (-node["depth"], node["id"]))
    registered_candidate_order = [node["id"] for node in candidate_nodes]

    for node in candidate_nodes:
        node_id = node["id"]
        reason = None
        if node_id == root_id:
            reason = "root"
        elif not node["removable"]:
            reason = "not_removable"
        elif node["symbol"] in required_set:
            reason = "required_symbol"
        else:
            retained_children = [child_id for child_id in children[node_id] if child_id in retained]
            if retained_children:
                reason = "retained_children"
            else:
                symbol = node["symbol"]
                retained_symbol_counts[symbol] -= 1
                retained.remove(node_id)
                if all(retained_symbol_counts.get(required, 0) > 0 for required in required_symbols):
                    removal_order.append(node_id)
                    decisions.append({
                        "id": node_id,
                        "symbol": symbol,
                        "depth": node["depth"],
                        "action": "remove",
                        "reason": "grammar_valid_interestingness_preserved",
                    })
                    continue
                retained.add(node_id)
                retained_symbol_counts[symbol] += 1
                reason = "required_symbols_not_represented"

        decisions.append({
            "id": node_id,
            "symbol": node["symbol"],
            "depth": node["depth"],
            "action": "retain",
            "reason": reason,
        })

    retained_ids = sorted(retained)
    removed_ids = list(removal_order)

    retained_symbol_counts_final = {}
    for node_id in retained_ids:
        symbol = by_id[node_id]["symbol"]
        retained_symbol_counts_final[symbol] = retained_symbol_counts_final.get(symbol, 0) + 1

    grammar_valid = root_id in retained
    for node_id in retained:
        if node_id == root_id:
            continue
        parent = by_id[node_id]["parent"]
        if parent not in retained:
            grammar_valid = False
            break

    interestingness_preserved = all(retained_symbol_counts_final.get(symbol, 0) > 0 for symbol in required_symbols)
    stable_ties = registered_candidate_order == [node["id"] for node in sorted(normalized_nodes, key=lambda node: (-node["depth"], node["id"]))]

    return {
        "retained_ids": retained_ids,
        "removed_ids": removed_ids,
        "removal_order": removal_order,
        "decisions": decisions,
        "required_symbols": list(required_symbols),
        "retained_symbol_counts": retained_symbol_counts_final,
        "removed_count": len(removed_ids),
        "retained_count": len(retained_ids),
        "grammar_valid": grammar_valid,
        "interestingness_preserved": interestingness_preserved,
        "registered_candidate_order": registered_candidate_order,
        "stable_ties": stable_ties,
    }
"}
